"""genui + the OpenAI Agents SDK: a streamed agent run, tool calls included, rendered as live UI.

Run:  pip install "genui-py[fastapi]" openai-agents uvicorn
      OPENAI_API_KEY=... uvicorn openai_agents_app:app --reload --port 8000
"""
import os
from pathlib import Path

from agents import Agent, Runner, function_tool
from fastapi import FastAPI, Request

from genui import Library
from genui.integrations.fastapi import read_run, stream_response
from genui.stream import ToolCallArgs, ToolCallEnd, ToolCallStart, ToolResult

# spec.json is generated by the React frontend (`npm run generate` in examples/fastapi-react/frontend).
SPEC = Path(__file__).resolve().parents[1] / "fastapi-react" / "backend" / "spec.json"
library = Library.from_spec(SPEC)


@function_tool
def get_weather(city: str) -> str:
    """Get the current weather for a city."""
    return f"18°C and sunny in {city}"


agent = Agent(name="assistant", instructions=library.system_prompt(), tools=[get_weather],
              model=os.environ.get("MODEL", "gpt-5.5-mini"))
app = FastAPI()


async def to_genui(result):
    """Raw model events carry the text (Responses API events genui understands); run items carry
    the tool calls and their outputs."""
    async for event in result.stream_events():
        if event.type == "raw_response_event":
            yield event.data  # response.output_text.delta etc.
        elif event.type == "run_item_stream_event" and event.name == "tool_called":
            item = event.item
            yield ToolCallStart(item.call_id, item.tool_name or "")
            yield ToolCallArgs(item.call_id, getattr(item.raw_item, "arguments", "") or "")
            yield ToolCallEnd(item.call_id)
        elif event.type == "run_item_stream_event" and event.name == "tool_output":
            yield ToolResult(event.item.call_id, str(event.item.output))


@app.post("/api/chat")
async def chat(request: Request):
    run = await read_run(request)
    history = [m for m in run.messages if m["role"] in ("user", "assistant") and m["content"]]
    result = Runner.run_streamed(agent, input=history)
    return stream_response(to_genui(result), run=run)
